import{c as t,Q as r,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const l=JSON.parse('{"title":"Claude Code 負責人宣布：Loop Engineering 取代 Prompt Engineering","description":"","frontmatter":{"url":"https://x.com/chenchengpro/status/2064221035734646916","title":"Claude Code 負責人宣布：Loop Engineering 取代 Prompt Engineering","author":"陈成","archived":"2026-06-15T00:00:00.000Z","category":"deep-application","handle":"@chenchengpro","published":"2026-06-09T00:00:00.000Z","score":"8.6/10","stats":"367❤ · 80 retweets","tags":["loop-engineering","claude-code","prompt-engineering","agentic-workflow"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-09-@chenchengpro-646916.md","filePath":"research/tweets/2026-06-09-@chenchengpro-646916.md","lastUpdated":1785909234000}'),a={name:"research/tweets/2026-06-09-@chenchengpro-646916.md"};function d(i,e,g,p,s,c){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-code-負責人宣布-loop-engineering-取代-prompt-engineering-—-chenchengpro" tabindex="-1">Claude Code 負責人宣布：Loop Engineering 取代 Prompt Engineering — @chenchengpro <a class="header-anchor" href="#claude-code-負責人宣布-loop-engineering-取代-prompt-engineering-—-chenchengpro" aria-label="Permalink to &quot;Claude Code 負責人宣布：Loop Engineering 取代 Prompt Engineering — @chenchengpro&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/chenchengpro/status/2064221035734646916" target="_blank" rel="noreferrer">https://x.com/chenchengpro/status/2064221035734646916</a><strong>類別</strong>：deep-application <strong>統計</strong>：367❤ · 80 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Code 负责人 @bcherny 说他已经不 prompt Claude 了。是循环在 prompt Claude、在决定下一步，他的活变成了写那个循环。Addy Osmani 给这事起了个名，叫 loop engineering：你不再是那个一轮轮敲 prompt 的人，而是搭一个会自己找活、分发、检查、记账、定下一步的系统，让它去捅 agent。</p><p>循环就五个零件，Claude Code 和 Codex 现在都备齐了。Automations 是心跳：定时自己跑、自己发现和分流，有结果进 Triage 收件箱，没结果就归档（/loop 按周期重跑，/goal 跑到你写的可验证条件为真才停，每轮完一个独立小模型来判断算不算完成，写代码的 agent 没资格给自己打分）。Worktrees：git worktree 给每个并行 agent 一份独立 checkout，从机制上断了它们踩同一个文件的可能。Skills：SKILL.md 把项目知识摊在外面，省得 agent 每次像金鱼一样重猜一遍，没它循环每轮都从零重推你的项目。Connectors（建在 MCP 上）：让循环够得着 issue tracker、数据库、staging API、Slack，差别就在「这是修复方案」和「自己开 PR、关联 ticket、CI 绿了就 ping 频道」之间。Sub-agents：写的人和检查的人分开，毕竟写代码的模型给自己打分总是手软。</p><p>还有第六件，最不起眼，可能也最要命：memory。一个 markdown 文件，或者一块 Linear board，活在单次对话之外，记着做过什么、下一步干嘛。模型每跑一次就忘光上一次，所以记忆得落在磁盘上，不能搁在 context 里。一句话，agent 会忘，repo 不会。</p><p>但有三件事循环没替你解决，而且循环越顺，这三件越扎手。第一，验证还是你的事：没人盯着的循环，也是在没人盯着地犯错，done 只是它的声明，不是证明。第二，你的理解会烂掉：循环越快地 ship 那些你没亲手写的代码，你和代码之间的鸿沟就越宽。第三，最舒服的姿势往往最危险——循环自己转起来，你很容易就不再有观点、照单全收。所以那句话是对的：Build the loop, stay the engineer，循环你来搭，但工程师这个位子得你自己坐着。</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>Loop Engineering 五個零件（Automations/Worktrees/Skills/Connectors/Sub-agents）可直接套用</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>系統化整理 Loop Engineering 範式，含三個警告（驗證/理解衰退/照單全收）</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>引用 Boris Cherny 原始觀點，有具體零件清單和機制說明</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>/loop vs /goal 機制、worktree 隔離、memory 磁盤化等技術點完整</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>範式轉移觀念適用所有 agentic workflow 設計</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.6/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Loop Engineering 五個零件框架適合整合進 core.md 的 agentic 設計原則，三個警告應加入 harness-meta GOTCHAS。</p>',12)])])}const m=t(a,[["render",d]]);export{l as __pageData,m as default};
